def calc(expr: str) -> int | str:
    s = expr
    n = len(s)
    i = 0

    def skip() -> None:
        nonlocal i
        while i < n and s[i] == " ":
            i += 1

    def trunc_div(a: int, b: int) -> int:
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def parse_expr() -> int | str:
        nonlocal i
        left = parse_term()
        if left == "error":
            return "error"
        while True:
            skip()
            if i >= n or s[i] not in "+-":
                return left
            op = s[i]
            i += 1
            right = parse_term()
            if right == "error":
                return "error"
            left = left + right if op == "+" else left - right

    def parse_term() -> int | str:
        nonlocal i
        left = parse_unary()
        if left == "error":
            return "error"
        while True:
            skip()
            if i >= n or s[i] not in "*/%":
                return left
            op = s[i]
            i += 1
            right = parse_unary()
            if right == "error":
                return "error"
            if op == "*":
                left = left * right
                continue
            if right == 0:
                return "error"
            q = trunc_div(left, right)
            left = q if op == "/" else left - right * q

    def parse_unary() -> int | str:
        nonlocal i
        skip()
        neg = False
        while i < n and s[i] == "-":
            neg = not neg
            i += 1
            skip()
        val = parse_power()
        if val == "error":
            return "error"
        return -val if neg else val

    def parse_power() -> int | str:
        nonlocal i
        # (minuses, base): minuses apply to that base raised to the tower above it.
        # a ^ -- b ^ - c  ==  a ^ (-- (b ^ (- c)))
        first = parse_primary()
        if first == "error":
            return "error"
        nodes: list[tuple[int, int]] = [(0, first)]
        while True:
            skip()
            if i >= n or s[i] != "^":
                break
            i += 1
            skip()
            minuses = 0
            while i < n and s[i] == "-":
                minuses += 1
                i += 1
                skip()
            atom = parse_primary()
            if atom == "error":
                return "error"
            nodes.append((minuses, atom))

        minuses, val = nodes[-1]
        if minuses & 1:
            val = -val
        for k in range(len(nodes) - 2, -1, -1):
            if val < 0:
                return "error"
            val = nodes[k][1] ** val
            if nodes[k][0] & 1:
                val = -val
        return val

    def parse_primary() -> int | str:
        nonlocal i
        skip()
        if s[i] == "(":
            i += 1
            val = parse_expr()
            skip()
            i += 1
            return val
        j = i
        while j < n and s[j].isdigit():
            j += 1
        val = int(s[i:j])
        i = j
        return val

    return parse_expr()
